<?php require 'common.php'; $mode=lab_mode(); $session=$_COOKIE[session_name()]??''; $simulated=$_GET['session']??$session; $valid=hash_equals($session,$simulated); $status=$mode==='fixed'&&!hash_equals($session,$simulated)?403:200; if($status===403)http_response_code(403); audit('Session Hijacking',$mode,'GET',$_SERVER['REQUEST_URI']??'',$status,$status===403?'blocked':'session-accepted','Lab-only simulation: fixed mode rejects a session identifier that does not match the current session.'); ?><!doctype html><html lang="vi"><head><meta charset="utf-8"><title>Session Hijacking Lab</title></head><body style="font-family:Arial;max-width:950px;margin:30px auto"><h1>Session Hijacking — Lab Simulation</h1><p>Mode: <b><?=h($mode)?></b></p><p>Current session cookie exists: <b><?=isset($_COOKIE[session_name()])?'YES':'NO'?></b></p><form><input name="session" value="<?=h($simulated)?>" size="65"><select name="mode"><option value="vulnerable">vulnerable</option><option value="fixed">fixed</option></select><button>Test session</button></form><h2>HTTP status: <?=$status?></h2><p><?= $status===403?'403 Forbidden — session identifier rejected.':'200 OK — lab session accepted.' ?></p><p>Phòng thủ: Secure/HttpOnly/SameSite cookies, TLS, session regeneration, timeout và logout invalidation. Chỉ mô phỏng trên localhost/VM.</p><a href="index.php">← Lab menu</a></body></html>